<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Avatars; use Symfony\Component\HttpFoundation\BinaryFileResponse; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class AvatarController extends ClientApiController { public function store(ClientApiRequest $request): JsonResponse { $request->validate([ 'avatar' => [ 'required', 'file', 'image', 'mimes:' . Avatars::MIMES, 'max:' . Avatars::MAX_KILOBYTES, 'dimensions:max_width=' . Avatars::MAX_SIDE . ',max_height=' . Avatars::MAX_SIDE, ], ]); $user = $request->user(); if (!Avatars::store($user, $request->file('avatar'))) { return new JsonResponse([ 'errors' => [['code' => 'BadImage', 'detail' => 'That picture could not be read as an image, or it holds more pixels than the panel will open.']], ], 422); } Activity::event('user:account.avatar-changed')->subject($user)->log(); return new JsonResponse(['avatar' => Avatars::custom($user->refresh())]); } public function destroy(ClientApiRequest $request): JsonResponse { $user = $request->user(); Avatars::forget($user); Activity::event('user:account.avatar-removed')->subject($user)->log(); return new JsonResponse(['avatar' => null]); } public function show(ClientApiRequest $request, string $uuid): BinaryFileResponse { $path = Avatars::stored(User::query()->where('uuid', $uuid)->first()); if ($path === null) { throw new NotFoundHttpException(); } return response()->file($path, [ 'Content-Type' => 'image/webp', 'Content-Disposition' => 'inline; filename="avatar.webp"', 'Content-Security-Policy' => "default-src 'none'; sandbox", 'X-Content-Type-Options' => 'nosniff', 'Cache-Control' => 'private, max-age=600', ]); } } 